// 示例代码：test_ai_infra_scale_mul_tiling.cpp（节选）
class AiInfraScaleMulTiling : public testing::Test { /* 照标本 */ };

TEST_F(AiInfraScaleMulTiling, ai_infra_scale_mul_bf16_4096_4_768_pangu_000000)
{
    int64_t S = 4096, B = 4, H = 768;
    optiling::AiInfraScaleMulCompileInfo compileInfo = {};
    gert::TilingContextPara para(
        "AiInfraScaleMul",                       // 注册名（OP_ADD 类名），不是目录名
        { {{{S, B, H}, {S, B, H}}, ge::DT_BF16, ge::FORMAT_ND},
          {{{H}, {H}},          ge::DT_BF16, ge::FORMAT_ND} },   // scale_vector [H]
        { {{{S, B, H}, {S, B, H}}, ge::DT_BF16, ge::FORMAT_ND} },
        {}, &compileInfo);

    ExecuteTestCase(para, ge::GRAPH_SUCCESS,
                    /*tilingKey=*/0,             // BF16 → 0
                    /*tilingData=*/"",
                    /*workspaces=*/{0});          // 我们的设计不需要 workspace
}

TEST_F(AiInfraScaleMulTiling, ai_infra_scale_mul_bf16_scaleLenMismatch_000000)
{
    int64_t S = 4096, B = 4, H = 768;
    optiling::AiInfraScaleMulCompileInfo compileInfo = {};
    gert::TilingContextPara para(
        "AiInfraScaleMul",
        { {{{S, B, H}, {S, B, H}}, ge::DT_BF16, ge::FORMAT_ND},
          {{{384}, {384}},        ge::DT_BF16, ge::FORMAT_ND} },  // 长度 != H
        { {{{S, B, H}, {S, B, H}}, ge::DT_BF16, ge::FORMAT_ND} },
        {}, &compileInfo);
    ExecuteTestCase(para, ge::GRAPH_FAILED, 0, "", {0});
}
